/**
 * Neighbourhood names (#10): each neighbourhood of houses a village grows gets an English-village street name ("Oak
 * Row", "Mill Lane"), shown on its houses' signs, the panel and the village summary. Generated by code, deterministic
 * (from the village's name and the neighbourhood's index), unique within a village and short enough for one sign line;
 * kept on the layout entry (`name`, lesson 103). A village from before has its names worked out the same way on first
 * need, so an old checkpoint shows them too. World-free.
 */
import { isDwelling } from './grow';
import { signLineWidth } from './streetPlan';
import type { Village } from './village';

/** First words: trees, the mill and the brook, fields, a church. */
const FIRST = ['Oak', 'Elm', 'Ash', 'Birch', 'Willow', 'Mill', 'Brook', 'Church', 'Orchard', 'Meadow', 'Hollow', 'Bridge',
  'Rose', 'Hazel', 'Cherry', 'Holly', 'Well', 'Stone', 'Barley', 'Chapel', 'Pine', 'Acacia', 'Sand', 'Frost'];
/** First words only for a wood or style they fit. */
const BIOME_ONLY = new Set(['Pine', 'Acacia', 'Sand', 'Frost']);
const SUFFIX = ['Row', 'Lane', 'Close', 'End', 'Green', 'Way', 'Street', 'Court', 'Rise', 'Walk'];
/** A first word that fits the village's wood, then ones that fit the style voted for (a biome's houses). */
const WOOD_WORD: Record<string, string> = { oak: 'Oak', birch: 'Birch', spruce: 'Pine', dark_oak: 'Elm', acacia: 'Acacia', cherry: 'Cherry', mangrove: 'Willow', pale_oak: 'Ash', jungle: 'Hazel' };
const STYLE_WORDS: Record<string, string[]> = { plains: ['Meadow', 'Barley', 'Mill'], desert: ['Sand', 'Well'], savanna: ['Acacia', 'Well'], snowy: ['Frost', 'Holly'], taiga: ['Pine', 'Brook'] };

/** FNV-1a of a string. */
function hash(s: string): number {
  let h = 0x811c9dc5;
  for (let i = 0; i < s.length; i++) h = Math.imul(h ^ s.charCodeAt(i), 0x01000193) >>> 0;
  return h;
}

/** Every name the generator can give, each one sign line wide at most (the font's 90 px). */
export const ALL_NAMES = FIRST.flatMap((f) => SUFFIX.map((s) => `${f} ${s}`)).filter((n) => signLineWidth(n) <= 90);

/**
 * The name for a village's neighbourhood `k` (its growth index, from 1), none of `used`: a first word that fits the
 * wood or the style (one not on any name yet) with a suffix by the hash, else a first word not used yet, else any name
 * not used, both in an order by the hash of the village's name and k.
 */
export function pickName(village: string, k: number, used: Iterable<string>, prefer: { wood?: string; style?: string } = {}): string {
  const taken = new Set(used);
  const firsts = new Set([...taken].map((n) => n.split(' ')[0]));
  const h = hash(`${village}:${k}`);
  const words = [...(prefer.wood && WOOD_WORD[prefer.wood] ? [WOOD_WORD[prefer.wood]] : []), ...(prefer.style ? STYLE_WORDS[prefer.style] ?? [] : [])];
  for (const f of words) {
    if (firsts.has(f)) continue;
    for (let i = 0; i < SUFFIX.length; i++) {
      const n = `${f} ${SUFFIX[(h + i) % SUFFIX.length]}`;
      if (!taken.has(n) && ALL_NAMES.includes(n)) return n;
    }
  }
  // (a biome's own words only where they fit: no "Frost End" in the plains)
  const order = ALL_NAMES.filter((n) => !BIOME_ONLY.has(n.split(' ')[0])).sort((a, b) => hash(`${h}:${a}`) - hash(`${h}:${b}`) || (a < b ? -1 : 1));
  return order.find((n) => !taken.has(n) && !firsts.has(n.split(' ')[0])) ?? order.find((n) => !taken.has(n)) ?? ALL_NAMES.find((n) => !taken.has(n)) ?? `Street ${k}`;
}

type Lay = NonNullable<Village['layouts']>[number];

/** Whether a layout is a neighbourhood of houses (a growth layout of dwellings, not a public work, X.2). */
export const isNeighbourhood = (l: Lay) => !!l.grow && l.buildings.length > 0 && l.buildings.every(isDwelling);

/** The style a neighbourhood was built in (its growth record's, spec_vote1). */
function styleOf(v: Village, layout: number): string | undefined {
  const g = v.growth;
  return (g?.active?.layout === layout ? g.active.style : undefined) ?? g?.past.find((p) => p.layout === layout)?.style;
}

/**
 * Every neighbourhood's name by layout number (from 1): the stored ones, then the others generated in layout order, none
 * a stored one's (pure: the same answer until a name is stored).
 */
export function neighbourhoodNames(v: Village): Map<number, string> {
  const out = new Map<number, string>();
  const lays = v.layouts ?? [];
  const used = new Set(lays.map((l) => l.name).filter((n): n is string => !!n));
  lays.forEach((l, i) => {
    if (!isNeighbourhood(l)) return;
    if (l.name) return void out.set(i + 1, l.name);
    const n = pickName(v.name, l.grow!, used, { wood: v.wood, style: styleOf(v, i + 1) });
    used.add(n);
    out.set(i + 1, n);
  });
  return out;
}

/** A neighbourhood's name (layout number from 1), or undefined for a layout that is not one. */
export const neighbourhoodName = (v: Village, layout: number): string | undefined => neighbourhoodNames(v).get(layout);

/** Store every neighbourhood's name on its layout (an old village's on first need); whether any was added. */
export function ensureNames(v: Village): boolean {
  let changed = false;
  for (const [n, name] of neighbourhoodNames(v)) {
    const l = v.layouts![n - 1];
    if (l.name !== name) l.name = name, changed = true;
  }
  return changed;
}

/** The name for the neighbourhood being laid out now (growth index `k`), after storing the others'. */
export function nameForNew(v: Village, k: number, wood?: string): string {
  ensureNames(v);
  // (the style the vote chose for it, kept on growth.next until its layout is posted; a choice by its residents, or the
  // vote itself, could name it here instead later, #10)
  return pickName(v.name, k, (v.layouts ?? []).map((l) => l.name).filter((n): n is string => !!n), { wood: wood ?? v.wood, style: v.growth?.next?.style || undefined });
}

/**
 * A signpost's text (a small work, s35; build_design sets it blank): the neighbourhood it stands in, else the nearest
 * one with its compass direction, else the village's name.
 */
export function signpostText(v: Village, x: number, z: number): string[] {
  const names = neighbourhoodNames(v);
  let best: { name: string; d: number; dx: number; dz: number } | null = null;
  for (const [n, name] of names) {
    const l = v.layouts![n - 1];
    if (x >= l.x1 && x <= l.x2 && z >= l.z1 && z <= l.z2) return [name];
    const dx = (l.x1 + l.x2) / 2 - x, dz = (l.z1 + l.z2) / 2 - z, d = Math.hypot(dx, dz);
    if (!best || d < best.d) best = { name, d, dx, dz };
  }
  if (!best) return signLabelLines(v.name);
  const dir = Math.abs(best.dx) > Math.abs(best.dz) ? (best.dx > 0 ? 'east' : 'west') : best.dz > 0 ? 'south' : 'north';
  return [best.name, `to the ${dir}`];
}

/** A village's name on a sign: cut to one line. */
function signLabelLines(name: string): string[] {
  let n = name;
  while (signLineWidth(n) > 90) n = n.slice(0, -1);
  return [n];
}
